SELECT table_name,COUNT(*) AS column_count FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name IN ('res_project','res_project_leader','res_project_lab','res_project_tag','res_project_member','res_batch','res_batch_leader','res_batch_member','res_culture','res_culture_leader','res_culture_member','res_culture_occupancy','res_culture_notice_outbox','res_culture_parameter_application','res_culture_parameter_snapshot','res_culture_parameter_state','res_culture_workflow_reference','res_culture_runtime_event') GROUP BY table_name ORDER BY table_name;
SELECT s.snapshot_id FROM res_culture_parameter_snapshot s LEFT JOIN res_culture c ON c.culture_id=s.culture_id WHERE c.culture_id IS NULL;
SELECT p.state_id FROM res_culture_parameter_state p LEFT JOIN res_culture_parameter_snapshot s ON s.snapshot_id=p.effective_snapshot_id WHERE p.effective_snapshot_id IS NOT NULL AND (s.snapshot_id IS NULL OR s.culture_id<>p.culture_id OR s.workflow_node_id<>p.workflow_node_id OR s.template_kind<>p.template_kind);
SELECT p.state_id FROM res_culture_parameter_state p LEFT JOIN res_culture_parameter_snapshot s ON s.snapshot_id=p.candidate_snapshot_id WHERE p.candidate_snapshot_id IS NOT NULL AND (s.snapshot_id IS NULL OR s.culture_id<>p.culture_id OR s.workflow_node_id<>p.workflow_node_id OR s.template_kind<>p.template_kind);
SELECT r.reference_id FROM res_culture_workflow_reference r LEFT JOIN res_culture c ON c.culture_id=r.culture_id WHERE c.culture_id IS NULL;
